  const sky = g.createLinearGradient(0, 0, 0, H);
  if (night) { sky.addColorStop(0, '#060812'); sky.addColorStop(0.6, mixHex('#141c30', T[1], 0.2)); sky.addColorStop(1, mixHex('#1c2438', T[1], 0.25)); }
